diff --git a/js/theme.js b/js/theme.js
new file mode 100644
index 0000000..b5af04a
--- /dev/null
+++ b/js/theme.js
@@ -0,0 +1,24 @@
+// Loaded with `async blocking="render"`: the stored theme is applied before the
+// first frame, so view transition snapshots never flash the wrong theme.
+const root = document.documentElement;
+const stored = localStorage.getItem('theme');
+const theme = stored || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
+root.dataset.theme = theme;
+
+document.addEventListener('click', (event) => {
+  const toggle = event.target.closest('.theme-toggle');
+  if (!toggle) return;
+  const next = root.dataset.theme === 'dark' ? 'light' : 'dark';
+  root.dataset.theme = next;
+  localStorage.setItem('theme', next);
+  toggle.setAttribute('aria-pressed', String(next === 'dark'));
+});
+
+// Async scripts may run before or after DOMContentLoaded.
+const syncToggle = () => document.querySelector('.theme-toggle')
+  ?.setAttribute('aria-pressed', String(root.dataset.theme === 'dark'));
+if (document.readyState === 'loading') {
+  document.addEventListener('DOMContentLoaded', syncToggle);
+} else {
+  syncToggle();
+}
