+          s = s + radiance(Ray(cam.o+d*140,d.norm()),0,Xi);
+          Vec r = s*(1./n);
+          c = c + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+        }
+      rgba[i*4+0] = toInt(c.x);
+      rgba[i*4+1] = toInt(c.y);
+      rgba[i*4+2] = toInt(c.z);
+      rgba[i*4+3] = 255;
+    }
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE int end_pass(){ return ++passes; }
+
+}
