new file mode 100644
index 0000000..025e4da
--- /dev/null
+++ b/js/keystore.js
@@ -0,0 +1,60 @@
+// Browser persistence for issuer signing keys and the trusted-signer list.
+//
+// Issuer keys live in IndexedDB, which can hold WebCrypto CryptoKey objects
+// without ever exposing their private key material. The ML-DSA secret key is
+// raw bytes (no WebCrypto support yet), so it is stored as-is.
+
+const DB_NAME = 'daily-grind-signing';
+const STORE = 'issuerKeys';
+const TRUST_KEY = 'dailyGrind.trustedSigners';
+
+let dbPromise;
+
+function openDb() {
+  dbPromise ??= new Promise((resolve, reject) => {
+    const req = indexedDB.open(DB_NAME, 1);
+    req.onupgradeneeded = () => req.result.createObjectStore(STORE, { keyPath: 'alg' });
+    req.onsuccess = () => resolve(req.result);
+    req.onerror = () => reject(req.error);
+  });
+  return dbPromise;
+}
+
+async function run(mode, fn) {
+  const db = await openDb();
+  return new Promise((resolve, reject) => {
+    const tx = db.transaction(STORE, mode);
+    const req = fn(tx.objectStore(STORE));
+    tx.oncomplete = () => resolve(req.result);
+    tx.onerror = () => reject(tx.error);
+  });
+}
+
+export const loadIssuerKey = (alg) => run('readonly', (s) => s.get(alg));
+export const saveIssuerKey = (key) => run('readwrite', (s) => s.put(key));
+export const deleteIssuerKey = (alg) => run('readwrite', (s) => s.delete(alg));
+
+export function loadTrustedSigners() {
+  try {
+    const list = JSON.parse(localStorage.getItem(TRUST_KEY) || '[]');
+    return Array.isArray(list) ? list : [];
+  } catch {
+    return [];
+  }
+}
+
+function saveTrustedSigners(list) {
+  localStorage.setItem(TRUST_KEY, JSON.stringify(list));
+}
+
+export function trustSigner({ alg, keyId, publicKeys, label }) {
+  const list = loadTrustedSigners().filter((t) => t.keyId !== keyId);
+  list.push({ alg, keyId, publicKeys, label, addedAt: new Date().toISOString() });
+  saveTrustedSigners(list);
+}
+
+export function untrustSigner(keyId) {
+  saveTrustedSigners(loadTrustedSigners().filter((t) => t.keyId !== keyId));
+}
+
+export const findTrustedSigner = (keyId) => loadTrustedSigners().find((t) => t.keyId === keyId);
