+++ b/js/signing.js
@@ -0,0 +1,287 @@
+// Digital signatures for Daily Grind receipts and gift vouchers.
+//
+// Classical algorithms use the browser's WebCrypto API (private keys are
+// non-extractable). ML-DSA-65 (FIPS 204) is a quantum-resistant scheme provided
+// by the vendored, audited @noble/post-quantum library. The hybrid mode signs
+// with both Ed25519 and ML-DSA-65 and only verifies if *both* signatures hold.
+//
+// No DOM or storage access here so the module can be unit-tested under Node.
+
+import { ml_dsa65 } from '../vendor/noble-ml-dsa65-0.7.1.min.js';
+
+export const FORMAT = 'daily-grind/signed-document@1';
+export const PUBLIC_KEY_FORMAT = 'daily-grind/public-key@1';
+export const DOC_TYPES = ['receipt', 'voucher'];
+
+// Prepended to every signed message so these signatures can never be replayed
+// as signatures over some other protocol's data (and vice versa).
+const DOMAIN = 'DailyGrind signed document v1\n';
+
+const subtle = globalThis.crypto.subtle;
+
+const PRIMITIVES = {
+  'ECDSA-P256': {
+    publicKeyLength: 65,
+    signatureLength: 64,
+    async generate() {
+      const kp = await subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign', 'verify']);
+      return { publicKey: new Uint8Array(await subtle.exportKey('raw', kp.publicKey)), privateKey: kp.privateKey };
+    },
+    async sign(privateKey, msg) {
+      return new Uint8Array(await subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, privateKey, msg));
+    },
+    async verify(publicKey, sig, msg) {
+      const key = await subtle.importKey('raw', publicKey, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['verify']);
+      return subtle.verify({ name: 'ECDSA', hash: 'SHA-256' }, key, sig, msg);
+    },
+  },
+  Ed25519: {
+    publicKeyLength: 32,
+    signatureLength: 64,
+    async generate() {
+      const kp = await subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify']);
+      return { publicKey: new Uint8Array(await subtle.exportKey('raw', kp.publicKey)), privateKey: kp.privateKey };
+    },
+    async sign(privateKey, msg) {
+      return new Uint8Array(await subtle.sign({ name: 'Ed25519' }, privateKey, msg));
+    },
+    async verify(publicKey, sig, msg) {
+      const key = await subtle.importKey('raw', publicKey, { name: 'Ed25519' }, false, ['verify']);
+      return subtle.verify({ name: 'Ed25519' }, key, sig, msg);
+    },
+  },
+  'ML-DSA-65': {
+    publicKeyLength: 1952,
+    signatureLength: 3309,
+    async generate() {
+      const { publicKey, secretKey } = ml_dsa65.keygen();
+      return { publicKey, privateKey: secretKey };
+    },
+    async sign(secretKey, msg) {
+      return ml_dsa65.sign(msg, secretKey);
+    },
+    async verify(publicKey, sig, msg) {
+      return ml_dsa65.verify(sig, msg, publicKey);
+    },
+  },
+};
+
+export const ALGORITHMS = {
+  'ECDSA-P256': {
+    label: 'ECDSA P-256',
+    family: 'Classical',
+    description: 'NIST curve, supported everywhere. Not quantum-resistant.',
+    components: ['ECDSA-P256'],
+  },
+  Ed25519: {
+    label: 'Ed25519',
+    family: 'Classical',
+    description: 'Fast, compact modern signatures. Not quantum-resistant.',
+    components: ['Ed25519'],
+  },
+  'ML-DSA-65': {
+    label: 'ML-DSA-65 (FIPS 204)',
+    family: 'Quantum-resistant',
+    description: 'NIST post-quantum lattice signature. Larger keys and signatures.',
+    components: ['ML-DSA-65'],
+  },
+  'Ed25519+ML-DSA-65': {
+    label: 'Hybrid Ed25519 + ML-DSA-65',
+    family: 'Hybrid',
+    description: 'Both signatures must verify, so it stays secure if either scheme is broken.',
+    components: ['Ed25519', 'ML-DSA-65'],
+  },
+};
+
+// ---------------------------------------------------------------------------
+// Encoding helpers
+
+const encoder = new TextEncoder();
+export const utf8 = (s) => encoder.encode(s);
+
+export function toBase64(bytes) {
+  let bin = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(bin);
+}
+
+export function fromBase64(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9+/]*={0,2}$/.test(str)) throw new Error('Invalid base64 data');
+  const bin = atob(str);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+const toHex = (bytes) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
+
+// Deterministic JSON: object keys sorted, no whitespace. Signer and verifier
+// must produce byte-identical input, regardless of how the JSON was formatted
+// or which order fields were written in.
+export function canonicalize(value) {
+  if (value === null) return 'null';
+  switch (typeof value) {
+    case 'boolean':
+      return String(value);
+    case 'string':
+      return JSON.stringify(value);
+    case 'number':
+      if (!Number.isFinite(value)) throw new Error('Non-finite numbers cannot be signed');
+      return JSON.stringify(value);
+    case 'object':
+      if (Array.isArray(value)) return `[${value.map(canonicalize).join(',')}]`;
+      return `{${Object.keys(value)
+        .sort()
+        .map((k) => {
+          if (value[k] === undefined) throw new Error(`Field "${k}" is undefined`);
+          return `${JSON.stringify(k)}:${canonicalize(value[k])}`;
+        })
+        .join(',')}}`;
+    default:
+      throw new Error(`Unsupported value of type ${typeof value}`);
+  }
+}
+
+const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
+
+// ---------------------------------------------------------------------------
+// Keys
+
+// Key ID binds the algorithm and every component public key, so a hybrid key
+// can't be downgraded to one of its components without changing its identity.
+export async function computeKeyId(alg, publicKeys) {
+  const digest = await subtle.digest('SHA-256', utf8(canonicalize({ alg, publicKeys: publicKeys.map(toBase64) })));
+  return toHex(new Uint8Array(digest).subarray(0, 16));
+}
+
+export const formatFingerprint = (keyId) => keyId.match(/.{1,4}/g).join(' ');
+
+const supportCache = new Map();
+
+export function isAlgorithmSupported(alg) {
+  if (!supportCache.has(alg)) {
+    supportCache.set(
+      alg,
+      Promise.all(ALGORITHMS[alg].components.map((c) => PRIMITIVES[c].generate())).then(
+        () => true,
+        () => false,
+      ),
+    );
+  }
+  return supportCache.get(alg);
+}
+
+export async function generateIssuerKey(alg) {
+  const spec = ALGORITHMS[alg];
+  if (!spec) throw new Error(`Unknown algorithm ${alg}`);
+  const pairs = await Promise.all(spec.components.map((c) => PRIMITIVES[c].generate()));
+  const publicKeys = pairs.map((p) => p.publicKey);
+  return {
+    alg,
+    keyId: await computeKeyId(alg, publicKeys),
+    publicKeys,
+    privateKeys: pairs.map((p) => p.privateKey),
+    createdAt: new Date().toISOString(),
+  };
+}
+
+function decodePublicKeys(alg, encoded) {
+  const spec = ALGORITHMS[alg];
+  if (!spec) throw new Error(`Unsupported algorithm "${alg}"`);
+  if (!Array.isArray(encoded) || encoded.length !== spec.components.length) {
+    throw new Error(`Expected ${spec.components.length} public key(s) for ${alg}`);
+  }
+  return encoded.map((b64, i) => {
+    const bytes = fromBase64(b64);
+    if (bytes.length !== PRIMITIVES[spec.components[i]].publicKeyLength) {
+      throw new Error(`Wrong ${spec.components[i]} public key length`);
+    }
+    return bytes;
+  });
+}
+
+export function exportPublicKey(issuerKey, label) {
+  return {
+    format: PUBLIC_KEY_FORMAT,
+    label,
+    alg: issuerKey.alg,
+    keyId: issuerKey.keyId,
+    publicKeys: issuerKey.publicKeys.map(toBase64),
+  };
+}
+
+// Validates a shared public key bundle and returns a normalised record.
+export async function parsePublicKey(bundle) {
+  if (!isPlainObject(bundle) || bundle.format !== PUBLIC_KEY_FORMAT) throw new Error('Not a Daily Grind public key');
+  const publicKeys = decodePublicKeys(bundle.alg, bundle.publicKeys);
+  const keyId = await computeKeyId(bundle.alg, publicKeys);
+  if (bundle.keyId !== undefined && bundle.keyId !== keyId) throw new Error('Key ID does not match the public key');
+  const label = typeof bundle.label === 'string' ? bundle.label.slice(0, 80) : '';
+  return { alg: bundle.alg, keyId, publicKeys: bundle.publicKeys, label };
+}
+
+// ---------------------------------------------------------------------------
+// Signing and verification
+
+function signingInput({ type, payload, signer }) {
+  // The signer block (algorithm + public keys) is itself signed, preventing
+  // algorithm substitution and key-swapping on an otherwise valid document.
+  return utf8(DOMAIN + canonicalize({ format: FORMAT, type, payload, signer }));
+}
+
+export async function signDocument(issuerKey, type, payload) {
+  if (!DOC_TYPES.includes(type)) throw new Error(`Unknown document type ${type}`);
+  const spec = ALGORITHMS[issuerKey.alg];
+  const signer = { alg: issuerKey.alg, keyId: issuerKey.keyId, publicKeys: issuerKey.publicKeys.map(toBase64) };
+  const msg = signingInput({ type, payload, signer });
+  const sigs = await Promise.all(spec.components.map((c, i) => PRIMITIVES[c].sign(issuerKey.privateKeys[i], msg)));
+  return { format: FORMAT, type, payload, signer, signatures: sigs.map(toBase64) };
+}
+
+const DOC_FIELDS = ['format', 'type', 'payload', 'signer', 'signatures'];
+
+// Returns { valid, reason, alg, keyId, components: [{ alg, valid }] }.
+// `valid` is about integrity and possession of the signing key only; whether
+// the signer is *trusted* is a separate decision made against a trust list.
+export async function verifyDocument(doc) {
+  const fail = (reason, extra = {}) => ({ valid: false, reason, components: [], ...extra });
+  try {
+    if (!isPlainObject(doc) || doc.format !== FORMAT) return fail('Not a Daily Grind signed document.');
+    const unknown = Object.keys(doc).filter((k) => !DOC_FIELDS.includes(k));
+    if (unknown.length) return fail(`Unexpected unsigned field(s): ${unknown.join(', ')}.`);
+    if (!DOC_TYPES.includes(doc.type)) return fail('Unknown document type.');
+    if (!isPlainObject(doc.payload)) return fail('Missing document contents.');
+    const { signer } = doc;
+    if (!isPlainObject(signer)) return fail('Missing signer information.');
+
+    const spec = ALGORITHMS[signer.alg];
+    if (!spec) return fail(`Unsupported signature algorithm "${signer.alg}".`);
+    const publicKeys = decodePublicKeys(signer.alg, signer.publicKeys);
+    const keyId = await computeKeyId(signer.alg, publicKeys);
+    const info = { alg: signer.alg, keyId };
+    if (signer.keyId !== keyId) return fail('Signer key ID does not match its public key.', info);
+
+    if (!Array.isArray(doc.signatures) || doc.signatures.length !== spec.components.length) {
+      return fail(`Expected ${spec.components.length} signature(s) for ${signer.alg}.`, info);
+    }
+    const msg = signingInput(doc);
+    const components = await Promise.all(
+      spec.components.map(async (c, i) => {
+        const sig = fromBase64(doc.signatures[i]);
+        const ok = sig.length === PRIMITIVES[c].signatureLength && (await PRIMITIVES[c].verify(publicKeys[i], sig, msg));
+        return { alg: c, valid: ok };
+      }),
+    );
+    const valid = components.every((c) => c.valid);
+    return {
+      valid,
+      reason: valid ? 'Signature is valid.' : 'Signature check failed: the document was altered or not signed by this key.',
+      components,
+      ...info,
+    };
+  } catch (err) {
+    return fail(`Malformed document: ${err.message}`);
+  }
+}
