       text-decoration: none;
       font-size: 0.85rem;
     }
+    /* Seasonal Favorites carousel */
+    .carousel {
+      max-width: 520px;
+      margin: 20px auto 0;
+    }
+
+    .carousel-viewport {
+      overflow: hidden;
+      border-radius: 8px;
+    }
+
+    .carousel-slide.is-current {
+      view-transition-name: seasonal-slide;
+    }
+
+    .carousel-controls {
+      display: flex;
+      justify-content: space-between;
+      align-items: center;
+      margin-top: 15px;
+    }
+
+    .carousel-controls button {
+      background: var(--primary);
+      color: white;
+      border: none;
+      padding: 8px 16px;
+      border-radius: 5px;
+      font: inherit;
+      cursor: pointer;
+      transition: background 0.3s;
+    }
+
+    .carousel-controls button:hover {
+      background: #3e2723;
+    }
+
+    .carousel-controls button:focus-visible {
+      outline: 3px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    @keyframes slide-from-right {
+      from { transform: translateX(100%); }
+    }
+
+    @keyframes slide-to-left {
+      to { transform: translateX(-100%); }
+    }
+
+    @keyframes slide-from-left {
+      from { transform: translateX(-100%); }
+    }
+
+    @keyframes slide-to-right {
+      to { transform: translateX(100%); }
+    }
+
+    ::view-transition-old(seasonal-slide),
+    ::view-transition-new(seasonal-slide) {
+      animation-duration: 0.4s;
+      animation-timing-function: ease-in-out;
+      animation-fill-mode: both;
+    }
+
+    /* The type matches on the transition's scope element */
+    :active-view-transition-type(next)::view-transition-old(seasonal-slide) {
+      animation-name: slide-to-left;
+    }
+
+    :active-view-transition-type(next)::view-transition-new(seasonal-slide) {
+      animation-name: slide-from-right;
+    }
+
+    :active-view-transition-type(previous)::view-transition-old(seasonal-slide) {
+      animation-name: slide-to-right;
+    }
+
+    :active-view-transition-type(previous)::view-transition-new(seasonal-slide) {
+      animation-name: slide-from-left;
+    }
+
+    /* Fallback when element-scoped view transitions aren't supported: slide in the new item only */
+    .carousel-slide.enter-next {
+      animation: slide-from-right 0.4s ease-in-out;
+    }
+
+    .carousel-slide.enter-previous {
+      animation: slide-from-left 0.4s ease-in-out;
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      ::view-transition-group(*),
