+  <script>
+    (() => {
+      const form = document.getElementById('rewards-form');
+      const steps = [...form.querySelectorAll('.step')];
+      const trackerItems = [...document.querySelectorAll('#rewards-progress li')];
+      const backBtn = document.getElementById('back-btn');
+      const submitBtn = document.getElementById('submit-btn');
+      const summary = document.getElementById('error-summary');
+      const errorList = document.getElementById('error-list');
+      const alertEl = document.getElementById('form-alert');
+      const statusEl = document.getElementById('form-status');
+      const reviewList = document.getElementById('review-list');
+      const passwordInput = document.getElementById('password');
+      const toggleBtn = document.getElementById('toggle-password');
+      const lastStep = steps.length - 1;
+      let current = 0;
+
+      // Without JS the whole form shows at once and submits natively.
+      // With JS we validate step by step ourselves.
+      form.noValidate = true;
+      document.getElementById('rewards-progress').hidden = false;
+      backBtn.hidden = false;
+      toggleBtn.hidden = false;
+      reviewList.hidden = false;
+
+      const controlsIn = (root) =>
+        [...root.querySelectorAll('input, select')].filter((el) => el.willValidate);
+
+      const labelFor = (el) => {
+        const label = form.querySelector(`label[for="${el.id}"]`);
+        return label ? label.textContent.replace('*', '').trim() : el.name;
+      };
+
+      const syncAria = (el) => {
+        const invalid = !el.checkValidity() &&
+          (el.matches(':user-invalid') || el.closest('.attempted') !== null);
+        if (invalid) {
+          el.setAttribute('aria-invalid', 'true');
+        } else {
+          el.removeAttribute('aria-invalid');
+        }
+      };
+
+      const clearSummary = () => {
+        summary.hidden = true;
+        errorList.replaceChildren();
+      };
+
+      const showErrors = (stepEl, invalid) => {
+        stepEl.classList.add('attempted');
+        invalid.forEach(syncAria);
+        errorList.replaceChildren(...invalid.map((el) => {
+          const li = document.createElement('li');
+          const a = document.createElement('a');
+          a.href = `#${el.id}`;
+          a.textContent = labelFor(el);
+          a.addEventListener('click', (e) => {
+            e.preventDefault();
+            el.focus();
+          });
+          li.append(a);
+          return li;
+        }));
+        summary.hidden = false;
+        summary.focus();
+      };
+
+      const validateStep = (index) => {
+        const invalid = controlsIn(steps[index]).filter((el) => !el.checkValidity());
+        if (invalid.length) {
+          showErrors(steps[index], invalid);
+          return false;
+        }
+        return true;
+      };
+
+      const buildReview = () => {
+        const data = new FormData(form);
+        const textOf = (id) => {
+          const el = document.getElementById(id);
+          return el.selectedIndex > 0 ? el.options[el.selectedIndex].text : el.value.trim();
+        };
+        const drink = form.querySelector('[name="favorite_drink"]:checked');
+        const offers = [...form.querySelectorAll('[name="offers"]:checked')]
+          .map((el) => labelFor(el)).join(', ');
+        const birthday = [textOf('bday-month'), data.get('bday_day')].filter(Boolean).join(' ');
+        const rows = [
+          ['Name', textOf('full-name'), 0],
+          ['Email', textOf('email'), 0],
+          ['Mobile', textOf('phone'), 1],
+          ['ZIP or postal code', textOf('postal-code'), 1],
+          ['Birthday', birthday, 1],
+          ['Home store', textOf('home-store'), 2],
+          ['Favorite drink', drink ? labelFor(drink) : '', 2],
+          ['Offers by', offers, 2],
+        ];
+
+        // textContent only: user input is never parsed as HTML
+        reviewList.replaceChildren(...rows.flatMap(([term, value, step]) => {
+          const dt = document.createElement('dt');
+          dt.textContent = term;
+          const dd = document.createElement('dd');
+          dd.textContent = value || 'Not provided';
+          const edit = document.createElement('button');
+          edit.type = 'button';
+          edit.className = 'btn-link';
+          edit.dataset.goto = step;
+          edit.textContent = 'Edit';
+          const hidden = document.createElement('span');
+          hidden.className = 'visually-hidden';
+          hidden.textContent = ` ${term.toLowerCase()}`;
+          edit.append(hidden);
+          dd.append(' ', edit);
+          return [dt, dd];
+        }));
+      };
+
+      const showStep = (index, moveFocus = true) => {
+        current = index;
+        clearSummary();
+        alertEl.textContent = '';
+        steps.forEach((step, i) => { step.hidden = i !== index; });
+        trackerItems.forEach((li, i) => {
+          li.classList.toggle('step-done', i < index);
