@@ -0,0 +1,44 @@
+// Test the pointer position, not event.target: the <dialog> is also the target for its own
+// padding and the gaps between its children, so a target check would close on those clicks.
+const isOutside = (event: PointerEvent, dialog: HTMLDialogElement) => {
+    const rect = dialog.getBoundingClientRect();
+    return (
+        event.clientX < rect.left ||
+        event.clientX > rect.right ||
+        event.clientY < rect.top ||
+        event.clientY > rect.bottom
+    );
+};
+
+/**
+ * Opens a <dialog closedby="any"> as a modal. Where `closedby` isn't supported
+ * (e.g. Safari), backdrop clicks are emulated so light dismiss works everywhere.
+ * Returns a cleanup function that removes the fallback listeners.
+ */
+export function showModalWithLightDismiss(dialog: HTMLDialogElement): () => void {
+    if (!dialog.open) {
+        dialog.showModal();
+    }
+
+    if ('closedBy' in HTMLDialogElement.prototype) {
+        return () => {};
+    }
+
+    let pressedOutside = false;
+    const onPointerDown = (event: PointerEvent) => {
+        pressedOutside = isOutside(event, dialog);
+    };
+    // Require the press and the release outside, so a text-selection drag that ends on the backdrop does not dismiss.
+    const onPointerUp = (event: PointerEvent) => {
+        if (pressedOutside && isOutside(event, dialog)) {
+            dialog.close();
+        }
+    };
+
+    dialog.addEventListener('pointerdown', onPointerDown);
+    dialog.addEventListener('pointerup', onPointerUp);
+    return () => {
+        dialog.removeEventListener('pointerdown', onPointerDown);
+        dialog.removeEventListener('pointerup', onPointerUp);
+    };
+}

