diff --git a/src/components/ModalDialog.tsx b/src/components/ModalDialog.tsx
new file mode 100644
index 0000000..33afa8d
--- /dev/null
+++ b/src/components/ModalDialog.tsx
@@ -0,0 +1,56 @@
+import React, { useEffect, useRef } from 'react';
+
+interface Props {
+  labelledBy: string;
+  onClose: () => void;
+  children: React.ReactNode;
+}
+
+// Native modal <dialog>: provides the top layer, inert background, focus trapping,
+// Escape-to-close and focus restoration to the opener on close.
+export default function ModalDialog({ labelledBy, onClose, children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (dialog && !dialog.open) {
+      dialog.showModal();
+      // React doesn't render the `autofocus` attribute, so mark the initial focus target explicitly.
+      dialog.querySelector<HTMLElement>('[data-autofocus]')?.focus();
+    }
+  }, []);
+
+  // Fallback light dismiss for browsers without `closedby` support:
+  // clicks on the ::backdrop target the <dialog> element itself.
+  const handleClick = (event: React.MouseEvent<HTMLDialogElement>) => {
+    if (event.target === event.currentTarget) {
+      event.currentTarget.close();
+    }
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={labelledBy}
+      closedby="any"
+      onClose={onClose}
+      onClick={handleClick}
+      className="modal-dialog bg-white shadow-xl"
+    >
+      <div className="relative">
+        <form method="dialog">
+          <button
+            type="submit"
+            aria-label="Close"
+            className="absolute -top-2 -right-2 bg-white rounded-full p-1 shadow-md text-gray-500 hover:text-amber-400 hover:scale-110 transition-transform z-10"
+          >
+            <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+            </svg>
+          </button>
+        </form>
+        {children}
+      </div>
+    </dialog>
+  );
+}
