--- /dev/null
+++ b/src/components/ReauthDialog.tsx
@@ -0,0 +1,148 @@
+import React, { useEffect, useRef, useState } from 'react';
+import { KeyIcon, ShieldCheckIcon } from '@heroicons/react/24/outline';
+import {
+  ApiError,
+  PasskeyCancelledError,
+  reauthenticateWithPasskey,
+  reauthenticateWithPassword,
+} from '../lib/auth/client';
+
+interface Props {
+  username: string;
+  hasPasskeys: boolean;
+  onSuccess: () => void;
+  onCancel: () => void;
+}
+
+/** Asks the signed-in user to confirm their identity before a sensitive change. */
+export default function ReauthDialog({ username, hasPasskeys, onSuccess, onCancel }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const [password, setPassword] = useState('');
+  const [showPassword, setShowPassword] = useState(!hasPasskeys);
+  const [error, setError] = useState<string | null>(null);
+  const [loading, setLoading] = useState(false);
+
+  useEffect(() => {
+    dialogRef.current?.showModal();
+  }, []);
+
+  const handlePasskey = async () => {
+    setError(null);
+    setLoading(true);
+    try {
+      await reauthenticateWithPasskey();
+      onSuccess();
+    } catch (err) {
+      if (!(err instanceof PasskeyCancelledError)) {
+        setError(err instanceof ApiError ? err.message : `Verification failed: ${(err as Error).message}`);
+      }
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  const handlePassword = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setLoading(true);
+    try {
+      await reauthenticateWithPassword(password);
+      onSuccess();
+    } catch (err) {
+      setError((err as Error).message);
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      onCancel={(e) => {
+        e.preventDefault();
+        onCancel();
+      }}
+      aria-labelledby="reauth-title"
+      className="m-auto w-full max-w-sm rounded-lg p-6 shadow-xl backdrop:bg-black/40"
+    >
+      <ShieldCheckIcon className="h-10 w-10 mx-auto text-gray-700 mb-3" aria-hidden="true" />
+      <h2 id="reauth-title" className="text-lg font-semibold text-center text-gray-800 mb-2">
+        Confirm it’s you
+      </h2>
+      <p className="text-sm text-center text-gray-600 mb-6">
+        For your security, please verify your identity to make changes to your sign-in methods.
+      </p>
+
+      {error && (
+        <div className="mb-4 p-3 text-sm text-red-700 bg-red-100 rounded-lg" role="alert">
+          {error}
+        </div>
+      )}
+
+      {hasPasskeys && (
+        <button
+          type="button"
+          onClick={handlePasskey}
+          disabled={loading}
+          autoFocus
+          className={`w-full flex items-center justify-center gap-2 py-2 px-4 rounded-md shadow-sm text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 ${
+            loading ? 'opacity-75 cursor-not-allowed' : ''
+          }`}
+        >
+          <KeyIcon className="h-5 w-5" aria-hidden="true" />
+          Verify with a passkey
+        </button>
+      )}
+
+      {hasPasskeys && !showPassword && (
+        <button
+          type="button"
+          onClick={() => setShowPassword(true)}
+          className="w-full mt-3 text-sm text-gray-600 underline hover:text-gray-900"
+        >
+          Use your password instead
+        </button>
+      )}
+
+      {showPassword && (
+        <form onSubmit={handlePassword} className={`space-y-4 ${hasPasskeys ? 'mt-6 pt-6 border-t border-gray-200' : ''}`}>
+          {/* Lets password managers match the saved credential. */}
+          <input type="text" name="username" autoComplete="username" value={username} readOnly hidden />
+          <div>
+            <label htmlFor="reauth-password" className="block text-sm font-medium text-gray-700 mb-1">
+              Password
+            </label>
+            <input
+              type="password"
+              id="reauth-password"
+              name="password"
+              autoComplete="current-password"
+              value={password}
+              onChange={(e) => setPassword(e.target.value)}
+              required
+              autoFocus={!hasPasskeys}
+              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
+            />
+          </div>
+          <button
+            type="submit"
+            disabled={loading}
+            className={`w-full py-2 px-4 rounded-md shadow-sm text-sm font-medium ${
+              hasPasskeys ? 'text-gray-800 bg-white border border-gray-300 hover:bg-gray-50' : 'text-white bg-gray-900 hover:bg-gray-800'
+            } focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 ${loading ? 'opacity-75 cursor-not-allowed' : ''}`}
+          >
+            {loading ? 'Verifying...' : 'Verify with password'}
+          </button>
+        </form>
+      )}
+
+      <button
+        type="button"
+        onClick={onCancel}
+        className="w-full mt-3 py-2 px-4 rounded-md text-sm font-medium text-gray-700 hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-gray-300"
+      >
+        Cancel
+      </button>
+    </dialog>
+  );
+}
