+      let pendingBack = null;
+
+      function goBack() {
+        pendingBack = new Promise((resolve) => {
+          window.addEventListener('popstate', () => {
+            pendingBack = null;
+            resolve();
+          }, { once: true });
+        });
+        history.back();
+      }
