+    (() => {
+      const ITEM_SELECTOR = 'a[href], button:not([disabled])';
+      const TOLERANCE = 1;
+      const FALLBACK_WEIGHT = 2;
+      const DIRECTIONS = {
+        ArrowUp: 'up',
+        ArrowDown: 'down',
+        ArrowLeft: 'left',
+        ArrowRight: 'right',
+      };
+
