+        '<button id="go" type="button">View Rewards</button>',
+        '<script>',
+        '(function(){',
+        'var nonce=null;',
+        'function send(msg){msg.nonce=nonce;parent.postMessage(msg,"*");}',
+        'addEventListener("message",function(e){',
+        '  if(e.source!==parent||nonce!==null)return;',
+        '  var d=e.data;',
+        '  if(!d||d.type!=="grind:widget-init"||typeof d.nonce!=="string")return;',
+        '  nonce=d.nonce;',
+        '  send({type:"grind:widget-ready"});',
+        '  send({type:"grind:widget-resize",height:document.documentElement.scrollHeight});',
+        '});',
+        'document.getElementById("go").addEventListener("click",function(){',
+        '  if(nonce!==null)send({type:"grind:widget-navigate",url:"/rewards"});',
+        '});',
+        '})();',
+        '<\/script></body></html>'
+      ].join('');
