+      var widgetFrame = null;
+      var widgetNonce = null;
+      // The widget's WindowProxy, pinned once its handshake succeeds.
+      var pinnedWidgetSource = null;
+
+      function generateNonce() {
+        var bytes = new Uint8Array(16);
