+// Server-side verification of Email Verification Protocol (EVP) presentations.
+// The browser submits `EVT~KB-JWT`: an issuer-signed SD-JWT proving the user
+// controls an email address, bound to our origin and per-form nonce.
+import { createHash } from 'node:crypto';
+import dns from 'node:dns/promises';
+import { decodeSdJwtSync, SDJwtInstance } from '@sd-jwt/core';
+import { createRemoteJWKSet, importJWK, jwtVerify } from 'jose';
+
+// IETF draft-hardt-email-verification specifies RFC 9864 'Ed25519' and 'ES256'.
+// TODO: Remove 'EdDSA' once live issuers and Chrome Origin Trial builds finish
+// transitioning from 'EdDSA' (with crv: 'Ed25519') to 'Ed25519'.
+const ALLOWED_ALGS = ['Ed25519', 'EdDSA', 'ES256'];
+const normalizeAlg = (alg) => (alg === 'Ed25519' ? 'EdDSA' : alg);
+
+const hasher = (data, alg) =>
+  createHash(alg === 'sha-256' ? 'sha256' : alg).update(data).digest();
+
+const jwksCache = new Map();
+
+async function resolveIssuerJwks(iss, fetchImpl) {
+  const discoveryUrl = new URL('/.well-known/email-verification', iss);
+  if (discoveryUrl.protocol !== 'https:') throw new Error('Issuer must use HTTPS.');
+  const res = await fetchImpl(discoveryUrl, { redirect: 'error', signal: AbortSignal.timeout(5000) });
+  if (!res.ok) throw new Error(`Issuer metadata request failed with ${res.status}.`);
+  const metadata = await res.json();
+  if (metadata.issuer !== iss || typeof metadata.jwks_uri !== 'string' || !metadata.jwks_uri.startsWith('https://')) {
+    throw new Error('Invalid issuer metadata or non-HTTPS jwks_uri.');
+  }
+  if (!jwksCache.has(metadata.jwks_uri)) {
+    jwksCache.set(metadata.jwks_uri, createRemoteJWKSet(new URL(metadata.jwks_uri)));
+  }
+  return jwksCache.get(metadata.jwks_uri);
+}
+
+async function assertDnsDelegation(domain, iss, resolveTxt) {
+  const txtRecords = (await resolveTxt(`_email-verification.${domain}`)).map((r) => r.join(''));
+  if (!txtRecords.some((txt) => txt.startsWith('iss=') && `https://${txt.slice(4).trim()}` === iss)) {
+    throw new Error(`Issuer "${iss}" is not delegated via DNS for "${domain}".`);
+  }
+}
+
+/**
+ * Throws unless `rawToken` cryptographically proves ownership of `submittedEmail`.
+ * `resolveTxt`, `fetchImpl`, and `getIssuerKeys` are injectable for tests.
+ */
+export async function verifyEmailVerificationToken({
+  rawToken,
+  submittedEmail,
+  expectedNonce,
+  expectedAudience,
+  resolveTxt = dns.resolveTxt,
+  fetchImpl = fetch,
+  getIssuerKeys = (iss) => resolveIssuerJwks(iss, fetchImpl),
+}) {
+  // Step 1: parse claims and match the submitted email.
+  const decoded = decodeSdJwtSync(rawToken, hasher);
+  const evtPayload = decoded.jwt?.payload ?? {};
+  const iss = evtPayload.iss;
+
+  if (!expectedNonce || !decoded.kbJwt || typeof iss !== 'string' || evtPayload.email_verified !== true) {
+    throw new Error('Missing nonce, KB-JWT, issuer, or email_verified !== true.');
+  }
+  if (typeof evtPayload.email !== 'string' || evtPayload.email.toLowerCase() !== submittedEmail.toLowerCase()) {
+    throw new Error('Submitted email does not match the EVT email claim.');
+  }
+
+  // Step 2: the email domain must delegate to this issuer before we contact it.
+  const domain = submittedEmail.slice(submittedEmail.lastIndexOf('@') + 1);
+  await assertDnsDelegation(domain, iss, resolveTxt);
+  const issuerKeys = await getIssuerKeys(iss);
+
+  // Step 3: verify the issuer signature and the browser's key binding.
+  const evtOptions = {
+    typ: 'ev+sd-jwt',
+    issuer: iss,
+    algorithms: ALLOWED_ALGS,
+    maxTokenAge: '5m',
+    clockTolerance: '1m',
+  };
+
+  const sdJwt = new SDJwtInstance({
+    hasher,
+    verifier: async (data, sig) => {
+      const compactEvt = `${data}.${sig}`;
+      try {
+        await jwtVerify(compactEvt, issuerKeys, evtOptions);
+      } catch (err) {
+        // Issuers such as Gmail omit `kid`; trial-verify each matching key.
+        if (err?.code !== 'ERR_JWKS_MULTIPLE_MATCHING_KEYS') throw err;
+        let matched = false;
+        for await (const publicKey of err) {
+          try {
+            await jwtVerify(compactEvt, publicKey, evtOptions);
+            matched = true;
+            break;
+          } catch {}
+        }
+        if (!matched) throw err;
+      }
+      return true;
+    },
+    kbVerifier: async (data, sig) => {
+      const holderJwk = evtPayload.cnf?.jwk;
+      const holderAlg = holderJwk?.alg;
+      const kbAlg = decoded.kbJwt.header?.alg;
+      if (
+        !holderAlg ||
+        !kbAlg ||
+        !ALLOWED_ALGS.includes(holderAlg) ||
+        !ALLOWED_ALGS.includes(kbAlg) ||
+        normalizeAlg(kbAlg) !== normalizeAlg(holderAlg)
+      ) {
+        throw new Error('Missing, disallowed, or mismatched KB-JWT algorithm.');
+      }
+      const holderKey = await importJWK(holderJwk, kbAlg);
+      await jwtVerify(`${data}.${sig}`, holderKey, {
+        typ: 'kb+jwt',
+        audience: expectedAudience,
+        algorithms: [kbAlg],
+        maxTokenAge: '5m',
+        clockTolerance: '1m',
+      });
+      return true;
+    },
+  });
+
+  await sdJwt.verify(rawToken, {
+    requiredClaimKeys: ['email', 'email_verified'],
+    keyBindingNonce: expectedNonce,
+    expectedKeyBindingAudience: expectedAudience,
+    keyBindingMaxAgeSeconds: 300,
+    skewSeconds: 60,
+  });
+
+  return { email: evtPayload.email, issuer: iss };
+}
