+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <slot></slot>
+  <div class="actions" part="actions"><slot name="action"></slot></div>
+`;
+
+/**
+ * <hero-banner image="..."> — full-width page banner.
+ *
+ * Use it in place of a <header> element; give it role="banner" (or wrap it in
+ * a <header>) to keep the landmark. The background image is decorative, so
+ * all meaningful text belongs in the slotted content.
+ *
+ * Attributes:
+ *   image — background image URL
+ *
+ * Slots:
+ *   (default) — heading and tagline
+ *   action    — call-to-action link, rendered as a button
+ *
+ * Parts: actions
+ */
+export class HeroBanner extends HTMLElement {
+  static observedAttributes = ['image'];
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [baseStyles, actionStyles, styles];
+    root.append(template.content.cloneNode(true));
+  }
+
+  attributeChangedCallback(name, _oldValue, newValue) {
+    if (name === 'image') {
+      if (newValue) {
+        this.style.setProperty('--hero-image', `url(${JSON.stringify(newValue)})`);
+      } else {
+        this.style.removeProperty('--hero-image');
+      }
+    }
+  }
